 for(const s of [-1,1]){if(s<0&&!arm)continue;g.push(B(1.7,4,1.9,s*5.3,12.6,0),B(1.5,3.8,1.7,s*5.3,9,1.2,-.35),B(1.9,1.4,2,s*5.3,6.9,2.2),B(.5,1.4,.5,s*5.3+.6,5.7,2.6),B(.5,1.4,.5,s*5.3-.6,5.7,2.6));}
